> = {
  [Product.NUCLEUM]: allDatafnFeatureIds,
  [Product.MEMOTRON]: ["system", "memory", "collections", "files"],
  [Product.POINTRON]: ["system", "focus", "calendar", "collections"]
};

function uniqueFeatureIds(
  featureIds: readonly DatafnFeatureId[]
): DatafnFeatureId[] {
  return [...new Set(featureIds)];
}

function filterRelationEndpoint(
  endpoint: DatafnRelationEndpoint,
  names: Set<string>
): DatafnRelationEndpoint | null {
  if (typeof endpoint === "string") {
    return names.has(endpoint) ? endpoint : null;
  }
  const next = endpoint.filter((name) => names.has(name));
  return next.length > 0 ? next : null;
}

function relationSortKey(relation: DatafnRelationDefinition) {
  const joinTable =
    typeof relation.joinTable === "string" ? relation.joinTable : undefined;
  const relationName =
    typeof relation.relation === "string" ? relation.relation : "";
  const inverse =
    typeof relation.inverse === "string" ? relation.inverse : undefined;
  return joinTable ?? relationName ?? inverse ?? "";
}

function compareByOrder(order: readonly string[], left: string, right: string) {
  const leftIndex = order.indexOf(left);
  const rightIndex = order.indexOf(right);
  const safeLeft = leftIndex === -1 ? order.length : leftIndex;
  const safeRight = rightIndex === -1 ? order.length : rightIndex;
  if (safeLeft !== safeRight) return safeLeft - safeRight;
  return left.localeCompare(right);
}

export type ComposedDatafnDefinition = {
  resources: DatafnResourceDefinition[];
  relations: DatafnRelationDefinition[];
};

/**
 * Builds the DataFn resource and relation lists for a feature set.
 * Cross-feature relations keep only endpoints present in the composed resources.
 */
export function composeDatafnDefinition(
  featureIds: readonly DatafnFeatureId[]
): ComposedDatafnDefinition {
  const resources: DatafnResourceDefinition[] = [];
  const seen = new Set<string>();
  for (const featureId of uniqueFeatureIds(featureIds)) {
    for (const resource of datafnFeatures[featureId].resources) {
      if (seen.has(resource.name)) continue;
      seen.add(resource.name);
      resources.push(resource);
    }
  }
  resources.sort((left, right) =>
    compareByOrder(datafnResourceOrder, left.name, right.name)
  );

  const names = new Set(resources.map((resource) => resource.name));
  const relations: DatafnRelationDefinition[] = [];
  const seenRelations = new Set<string>();
  for (const featureId of uniqueFeatureIds(featureIds)) {
    for (const relation of datafnFeatures[featureId].relations) {
      const from = filterRelationEndpoint(relation.from, names);
      const to = filterRelationEndpoint(relation.to, names);
      if (!from || !to) continue;
      const next = { ...relation, from, to };
      const key = `${relationSortKey(next)}:${JSON.stringify(from)}:${JSON.stringify(to)}`;
      if (seenRelations.has(key)) continue;
      seenRelations.add(key);
      relations.push(next);
    }
  }
  relations.sort((left, right) =>
    compareByOrder(
      datafnRelationOrder,
      relationSortKey(left),
      relationSortKey(right)
    )
  );

  return { resources, relations };
}

/**
 * Resource names owned by a product's feature set, including remote-only tables.
 */
export function resolveDatafnProductTableNames(
  product: Product | string
): string[] {
  const featureIds = productDatafnFeatures[product as Product];
  if (!featureIds) return [];
  return composeDatafnDefinition(featureIds).resources.map(
    (resource) => resource.name
  );
}

