import { describe, expect, it } from "vitest";
import { Product } from "@21n/shared-config/product.type";
import { nucleumDatafnSchema } from "./schema.datafn";
import {
  allDatafnFeatureIds,
  composeDatafnDefinition,
  resolveDatafnProductTableNames
} from "./schema.features";

describe("DataFn feature composition", () => {
  it("builds the union schema from every feature", () => {
    const composed = composeDatafnDefinition(allDatafnFeatureIds);
    expect(composed.resources.map((resource) => resource.name)).toEqual(
      nucleumDatafnSchema.resources.map((resource) => resource.name)
    );
    expect(composed.relations).toHaveLength(nucleumDatafnSchema.relations.length);
  });

  it("derives product table sets from feature combinations", () => {
    expect(resolveDatafnProductTableNames(Product.MEMOTRON)).toEqual([
      "accessLog",
      "capture",
      "collection",
      "file",
      "linkTag",
      "node",
      "property",
      "vector",
      "view"
    ]);
    expect(resolveDatafnProductTableNames(Product.POINTRON)).toEqual([
      "accessLog",
      "collection",
      "event",
      "objective",
      "linkTag",
      "property",
      "session",
      "sessionLog",
      "task",
      "view"
    ]);
    expect(resolveDatafnProductTableNames(Product.NUCLEUM)).toEqual(
      nucleumDatafnSchema.resources.map((resource) => resource.name)
    );
  });

  it("drops relation endpoints that are outside the feature set", () => {
    const memotron = composeDatafnDefinition([
      "system",
      "memory",
      "collections",
      "files"
    ]);
    const collectionItems = memotron.relations.find(
      (relation) => relation.joinTable === "collection_items"
    );
    expect(collectionItems?.from).toEqual(["node"]);
    expect(
      memotron.resources.some((resource) => resource.name === "objective")
    ).toBe(false);
  });
});

